#include <vector>
#include <queue>

using namespace std;

// Structure to store element value and its origin array indices
struct QueueNode {
    int value;
    int elementIndex;
    int listIndex;

    // Comparator to make this a min-heap
    bool operator>(const QueueNode& other) const {
        return value > other.value;
    }
};

class KWayMergeTemplate {
public:
    vector<int> mergeKSortedArrays(const vector<vector<int>>& lists) {
        priority_queue<QueueNode, vector<QueueNode>, greater<QueueNode>> minHeap;

        // Push the first element of each non-empty list onto the heap
        for (int i = 0; i < lists.size(); ++i) {
            if (!lists[i].empty()) {
                minHeap.push({lists[i][0], 0, i});
            }
        }

        vector<int> result;

        while (!minHeap.empty()) {
            QueueNode curr = minHeap.top();
            minHeap.pop();

            result.push_back(curr.value);

            int nextElementIndex = curr.elementIndex + 1;
            int listIdx = curr.listIndex;

            // If the same list has a next element, push it onto the heap
            if (nextElementIndex < lists[listIdx].size()) {
                minHeap.push({lists[listIdx][nextElementIndex], nextElementIndex, listIdx});
            }
        }

        return result;
    }
};

